{
  "explanation": "The infinite series ½ + ¼ + ⅛ + … is a geometric series with first term a = ½ and common ratio r = ½. Its sum is a/(1−r) = 1. Visually, start with a unit square and repeatedly shade half of whatever space remains: the first piece has area ½, the next ¼, then ⅛, and so on. The shaded regions pack the square without overlap or going outside, so their total area approaches 1.",
  "manimCode": "const side = 3.6;
const blx = -5.2;
const bly = -2.2;
const maxN = 12;
const colors = [BLUE, TEAL, GREEN, YELLOW, ORANGE, GOLD, RED, MAROON, PURPLE, BLUE_B, GREEN_B, TEAL_B];

function computePieces(n) {
  const pieces = [];
  let rx = 0, ry = 0, rw = 1, rh = 1;
  for (let k = 0; k < n; k++) {
    if (k % 2 === 0) {
      pieces.push({ x: rx, y: ry, w: rw / 2, h: rh, k });
      rx = rx + rw / 2;
      rw = rw / 2;
    } else {
      pieces.push({ x: rx, y: ry, w: rw, h: rh / 2, k });
      ry = ry + rh / 2;
      rh = rh / 2;
    }
  }
  return { pieces, rem: { x: rx, y: ry, w: rw, h: rh } };
}

function makeRect(p, color, opacity) {
  const w = Math.max(p.w * side, 0.01);
  const h = Math.max(p.h * side, 0.01);
  const rect = new Rectangle({ width: w, height: h, color: color });
  rect.setFill(color, opacity);
  rect.setStrokeWidth(1.5);
  rect.moveTo([blx + p.x * side + w / 2, bly + p.y * side + h / 2, 0]);
  return rect;
}

const border = new Square({ sideLength: side, color: WHITE });
border.moveTo([blx + side / 2, bly + side / 2, 0]);
border.setStrokeWidth(3);
border.setFillOpacity(0);
scene.add(border);

const title = new MathTex({ latex: '\\tfrac{1}{2}+\\tfrac{1}{4}+\\tfrac{1}{8}+\\cdots = 1' });
await title.waitForRender();
title.moveTo([2.8, 3.0, 0]);
title.scale(0.85);
scene.add(title);

let pieceMobs = [];
let labelMobs = [];
let remMob = null;
let sumLabel = null;
let currentN = 0;

const fracLatex = (k) => '\\tfrac{1}{' + Math.pow(2, k + 1) + '}';

async function buildLabels(pieces) {
  const labs = [];
  for (const p of pieces) {
    if (p.w * side < 0.35 || p.h * side < 0.35) continue;
    const lab = new MathTex({ latex: fracLatex(p.k) });
    await lab.waitForRender();
    lab.scale(Math.min(0.7, p.w * side * 0.55, p.h * side * 0.55));
    lab.moveTo([
      blx + (p.x + p.w / 2) * side,
      bly + (p.y + p.h / 2) * side,
      0
    ]);
    labs.push(lab);
  }
  return labs;
}

function partialSum(n) {
  return 1 - Math.pow(0.5, n);
}

async function updateSumLabel(n) {
  if (sumLabel) scene.remove(sumLabel);
  const s = partialSum(n);
  const sStr = s.toFixed(4).replace(/0+$/, '').replace(/\.$/, '');
  const latex = n === 0
    ? 'S_0 = 0'
    : 'S_{' + n + '} = ' + sStr + (n >= maxN ? '\\approx 1' : '');
  sumLabel = new MathTex({ latex });
  await sumLabel.waitForRender();
  sumLabel.scale(0.75);
  sumLabel.moveTo([2.8, 1.8, 0]);
  scene.add(sumLabel);
}

async function showN(n, animate) {
  for (const m of pieceMobs) scene.remove(m);
  for (const m of labelMobs) scene.remove(m);
  if (remMob) scene.remove(remMob);
  pieceMobs = [];
  labelMobs = [];
  remMob = null;
  currentN = n;

  const { pieces, rem } = computePieces(n);

  for (let i = 0; i < pieces.length; i++) {
    const rect = makeRect(pieces[i], colors[i % colors.length], 0.75);
    pieceMobs.push(rect);
    if (animate) {
      scene.add(rect);
      await scene.play(new FadeIn(rect));
    } else {
      scene.add(rect);
    }
  }

  if (rem.w > 1e-6 && rem.h > 1e-6) {
    remMob = makeRect(rem, GRAY, 0.15);
    remMob.setStrokeWidth(1);
    scene.add(remMob);
  }

  labelMobs = await buildLabels(pieces);
  for (const lab of labelMobs) scene.add(lab);

  await updateSumLabel(n);
}

await showN(1, true);
await scene.wait(0.3);
for (let n = 2; n <= 6; n++) {
  await showN(n, true);
  await scene.wait(0.25);
}
await showN(8, false);

const hint = new Text({ text: 'Drag slider to add terms', color: GRAY, fontSize: 22 });
hint.moveTo([2.8, -2.8, 0]);
scene.add(hint);

const controls = new Controls(scene, { position: 'bottom-right', theme: 'dark', width: 260 });
controls.addSlider({
  label: 'Terms n',
  min: 0,
  max: maxN,
  value: 8,
  step: 1,
  onChange: (val) => {
    showN(Math.round(val), false);
  }
});
controls.addButton({
  label: 'Animate fill',
  onClick: async () => {
    for (let n = 0; n <= maxN; n++) {
      await showN(n, false);
      await scene.wait(0.15);
    }
  }
});

await scene.wait(999999);"
